-- PT126-S4-Q14. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT126-S4-Q14$batch05$ AND q.stimulus=$batch05$In 1963, a young macaque monkey was observed venturing into a hot spring to retrieve food which had fallen in. Soon, other macaques began to enter the spring, and over a few years this behavior was adopted by the entire troop. Prior to 1963, no macaques had ever been observed in the hot spring; by 1990, the troop was regularly spending time there during the winters. Thus, these macaques are able to adopt and pass on new patterns of social behavior, and are not complete captives of their genetic heritage.$batch05$ AND q.prompt=$batch05$Which one of the following is an assumption required by the argument above?$batch05$ AND q.correct_choice=$batch05$B$batch05$) THEN RAISE EXCEPTION 'Question changed: PT126-S4-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT126-S4-Q14$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT126-S4-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT126-S4-Q14$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$These macaques can adopt and pass on new social behavior, and are not complete captives of their genes.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$One macaque went into a hot spring in 1963. Within a few years the whole troop did it, and by 1990 the troop regularly spent winters there.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The author reads the spread of the behavior as learning. But what if the behavior was genetic all along, waiting for the right moment to show up? Then it would not be a new behavior passed on socially. The answer has to rule out that the genes explain it.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A defender: the new behavior was not simply set by the macaques' genes.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT126-S4-Q14$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$If genes can change in a few years, a genetic explanation becomes *more* plausible. That hurts the author.$batch05$), ($batch05$B$batch05$, $batch05$"Not necessarily" is soft, and soft is exactly what a necessary assumption should be. Negate it: "new behaviors that appear in a few years *are* genetically predetermined." Then the hot spring habit came from genes, not social learning, and the conclusion falls.$batch05$), ($batch05$C$batch05$, $batch05$This sets a rule for concluding that genes changed. The author is concluding the opposite.$batch05$), ($batch05$D$batch05$, $batch05$This is the most popular wrong answer, and it is easy to see why: it sounds like the conclusion. But the author says the macaques are not *complete* captives of their genes. That leaves room for genes to matter a lot. "Completely independent" goes far beyond what the argument needs.$batch05$), ($batch05$E$batch05$, $batch05$The argument is about the ability to adopt and pass on behavior. It does not need this habit to last for generations.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT126-S4-Q14$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
